#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
void SelectionSort(vector<int>&a) {
    for(int i=0;i+1<(int)a.size();i++) {
        int k=i;
        // Tìm vị trí nhỏ nhất trong đoạn chưa sắp, chưa đổi chỗ ngay.
        for(int j=i+1;j<(int)a.size();j++) {
            if(a[j]<a[k])k=j;
        }
        swap(a[i],a[k]);
    }
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    SelectionSort(a);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

#include <iostream>
