using namespace std;
void InsertionSort(vector<int>&a) {
    for(int i=1;i<(int)a.size();i++) {
        int x=a[i],j=i-1;
        // Giữ x ở biến tạm trước khi dịch các số lớn hơn sang phải.
        while(j>=0&&a[j]>x) {
            a[j+1]=a[j];
            j--;
        }
        a[j+1]=x;
    }
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    InsertionSort(a);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

