void BubbleSort(vector<int>&a) {
    // Theo slide Thầy Văn: mỗi lượt đưa phần tử nhỏ về đầu đoạn.
    for(int i=0;i+1<(int)a.size();i++)
    for(int j=(int)a.size()-1;j>i;j--) {
        if(a[j-1]>a[j])swap(a[j-1],a[j]);
    }
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    BubbleSort(a);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

#include <iostream>
