#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
int Partition(vector<int>&a,int p,int r) {
    int t=p,x=a[r];
    // Đoạn [p,t) chứa các phần tử <= chốt x.
    for(int i=p;i<r;i++) {
        if(a[i]<=x) {
            swap(a[i],a[t]);
            t++;
        }
    }
    swap(a[t],a[r]);
    return t;
}
void QuickSort(vector<int>&a,int p,int r) {
    if(p>=r)return;
    int t=Partition(a,p,r);
    QuickSort(a,p,t-1);
    QuickSort(a,t+1,r);
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    QuickSort(a,0,n-1);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
void QuickSort(vector<int>&a,int p,int r) {
    if(p>=r)return;
    int i=p,j=r,x=a[p+(r-p)/2];
    do {
        while(a[i]<x)i++;
        while(a[j]>x)j--;
        if(i<=j) {
            swap(a[i],a[j]);
            i++;
            j--;
        }
    }
    while(i<=j);
    if(p<j)QuickSort(a,p,j);
    if(i<r)QuickSort(a,i,r);
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    QuickSort(a,0,n-1);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

#include <iostream>
