#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
void Merge(vector<int>&a,int p,int m,int r) {
    vector<int>b;
    int i=p,j=m+1;
    // Hai đoạn đều đã sắp; chọn đầu nhỏ hơn, ưu tiên trái khi bằng nhau.
    while(i<=m&&j<=r) {
        if(a[i]<=a[j])b.push_back(a[i++]);
        else b.push_back(a[j++]);
    }
    while(i<=m)b.push_back(a[i++]);
    while(j<=r)b.push_back(a[j++]);
    for(int k=0;k<(int)b.size();k++)a[p+k]=b[k];
}
void MergeSort(vector<int>&a,int p,int r) {
    if(p>=r)return;
    int m=p+(r-p)/2;
    MergeSort(a,p,m);
    MergeSort(a,m+1,r);
    Merge(a,p,m,r);
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    MergeSort(a,0,n-1);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
void AdjustHeap(vector<int>&a,int n,int i) {
    int k=i,p=2*i+1,r=2*i+2;
    if(p<n&&a[p]>a[k])k=p;
    if(r<n&&a[r]>a[k])k=r;
    if(k!=i) {
        swap(a[i],a[k]);
        AdjustHeap(a,n,k);
    }
}
void HeapSort(vector<int>&a) {
    int n=a.size();
    // Xây heap từ nút cha cuối về gốc: tổng thời gian O(n).
    for(int i=n/2-1;i>=0;i--)AdjustHeap(a,n,i);
    for(int last=n-1;last>0;last--) {
        swap(a[0],a[last]);
        AdjustHeap(a,last,0);
    }
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>200)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    HeapSort(a);
    for(int x:a)cout<<x<<' ';
    cout<<'\n';
}

