int Tim(vector<int>&a,int x) {
    int p=0,r=(int)a.size()-1;
    while(p<=r) {
        int m=p+(r-p)/2;
        if(a[m]==x)return m;
        if(a[m]<x)p=m+1;
        else r=m-1;
    }
    return -1;
}
