double Mu(double x,long long n) {
    if(n==0)return 1;
    double tam=Mu(x,n/2);
    double k=tam*tam;
    if(n%2)k*=x;
    return k;
}
int main() {
    double x;
    int n;
    if(!(cin>>x>>n)||n< -30||n>30)return 1;
    if(x==0&&n<0) {
        cout<<"Khong xac dinh";
        return 0;
    }
    long long e=n;
    double k=e<0?1/Mu(x,-e):Mu(x,e);
    cout<<k;
}

