using namespace std;
vector<vector<int> >cot(3);
void Hanoi(int n,int a,int b,int c) {
    if(n==0)return;
    Hanoi(n-1,a,c,b);
    int dia=cot[a].back();
    cot[a].pop_back();
    cot[b].push_back(dia);
    cout<<dia<<':'<<char('A'+a)<<"->"<<char('A'+b)<<' ';
    Hanoi(n-1,c,b,a);
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>8)return 1;
    for(int i=n;i>=1;i--)cot[0].push_back(i);
    Hanoi(n,0,1,2);
}

