using namespace std;
int n,dem=0;
vector<int>a;
bool AnToan(int c,int r) {
    for(int j=0;j<c;j++)if(a[j]==r||abs(a[j]-r)==c-j)return false;
    return true;
}
void Dat(int c) {
    if(c==n) {
        dem++;
        return;
    }
    for(int r=0;r<n;r++)if(AnToan(c,r)) {
