#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
struct Node {
    double data;
    Node*next;
    Node(double x):data(x),next(NULL) {
    }
}
;
class List {
    Node*head;
    public:
    List():head(NULL) {
    }
    ~List() {
        Clear();
    }
    bool IsEmpty()const {
        return head==NULL;
    }
    Node*InsertNode(int index,double x) {
        if(index<0)return NULL;
        Node*cur=head;
        for(int i=1;cur&&i<index;i++)cur=cur->next;
        if(index>0&&!cur)return NULL;
        Node*p=new Node(x);
        if(index==0) {
            p->next=head;
            head=p;
        }
        else {
            p->next=cur->next;
            cur->next=p;
        }
        return p;
    }
    int FindNode(double x)const {
        Node*p=head;
        int i=1;
        while(p) {
            if(p->data==x)return i;
            p=p->next;
            i++;
        }
        return 0;
    }
    int DeleteNode(double x) {
        Node*prev=NULL,*cur=head;
        int i=1;
        while(cur&&cur->data!=x) {
            prev=cur;
            cur=cur->next;
            i++;
        }
        if(!cur)return 0;
        // Nối bỏ qua nút trước khi delete, không đọc cur sau khi hủy.
        if(prev)prev->next=cur->next;
        else head=cur->next;
        delete cur;
        return i;
    }
    void Reverse() {
        Node*prev=NULL;
        while(head) {
            Node*next=head->next;
            head->next=prev;
            prev=head;
            head=next;
        }
        head=prev;
    }
    void Split(List&back) {
        back.Clear();
        if(!head)return;
        Node*slow=head,*fast=head->next;
        while(fast&&fast->next) {
            slow=slow->next;
            fast=fast->next->next;
        }
        back.head=slow->next;
        slow->next=NULL;
    }
    void Clear() {
        while(head) {
            Node*p=head;
            head=head->next;
            delete p;
        }
    }
    void DisplayList()const {
        for(Node*p=head;p;p=p->next)cout<<p->data<<' ';
    }
    // Không sao chép đối tượng đang sở hữu các nút;tránh hai destructor xóa cùng nút.
    List(const List&)=delete;
    List&operator=(const List&)=delete;
}
;
int main() {
    int n,m;
    if(!(cin>>n)||n<0||n>50)return 1;
    List list;
    for(int i=0;i<n;i++) {
        double x;
        cin>>x;
        list.InsertNode(i,x);
    }
    cin>>m;
    while(m--) {
        char c;
        cin>>c;
        if(c=='I') {
            int i;
            double x;
            cin>>i>>x;
            list.InsertNode(i,x);
        }
        else if(c=='D') {
            double x;
            cin>>x;
            list.DeleteNode(x);
        }
        else if(c=='R')list.Reverse();
        else if(c=='F') {
            double x;
            cin>>x;
            cout<<list.FindNode(x)<<' ';
        }
        else if(c=='S') {
            List b;
            list.Split(b);
            list.DisplayList();
            cout<<"| ";
            b.DisplayList();
            return 0;
        }
    }
    list.DisplayList();
}

