#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
struct Node {
    int info;
    Node*next;
}
;
Node*TaoNut(int x) {
    Node*p=new Node;
    p->info=x;
    p->next=NULL;
    return p;
}
void ChenDau(Node*&head,int x) {
    Node*p=TaoNut(x);
    p->next=head;
    head=p;
}
void ChenCuoi(Node*&head,int x) {
    Node*p=TaoNut(x);
    if(!head)head=p;
    else {
        Node*q=head;
        while(q->next)q=q->next;
        q->next=p;
    }
}
Node*TimKiem(Node*head,int x) {
    for(Node*p=head;p;p=p->next)if(p->info==x)return p;
    return NULL;
}
void XoaDau(Node*&head) {
    if(!head)return;
    Node*p=head;
    head=p->next;
    delete p;
}
void XoaCuoi(Node*&head) {
    if(!head)return;
    if(!head->next) {
        XoaDau(head);
        return;
    }
    Node*p=head;
    while(p->next->next)p=p->next;
    delete p->next;
    p->next=NULL;
}
void DaoNguoc(Node*&head) {
    Node*prev=NULL;
    while(head) {
        Node*q=head->next;
        head->next=prev;
        prev=head;
        head=q;
    }
    head=prev;
}
void Duyet(Node*head) {
    for(Node*p=head;p;p=p->next)cout<<p->info<<' ';
}
void Dispose(Node*&head) {
    while(head)XoaDau(head);
}
int main() {
    int n,m;
    if(!(cin>>n)||n<0||n>50)return 1;
    Node*head=NULL;
    for(int i=0,x;i<n;i++) {
        cin>>x;
        ChenCuoi(head,x);
    }
    cin>>m;
    while(m--) {
        char c;
        cin>>c;
        if(c=='H') {
            int x;
            cin>>x;
            ChenDau(head,x);
        }
        else if(c=='T') {
            int x;
            cin>>x;
            ChenCuoi(head,x);
        }
        else if(c=='D')XoaDau(head);
        else if(c=='E')XoaCuoi(head);
        else if(c=='R')DaoNguoc(head);
    }
    Duyet(head);
    Dispose(head);
}

