#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
class Stack {
    vector<int> values;
    int topIndex;
    public:Stack(int cap):values(cap),topIndex(-1) {
    }
    bool isEmpty() {
        return topIndex==-1;
    }
    bool isFull() {
        return topIndex+1==(int)values.size();
    }
    bool push(int x) {
        if(isFull())return false;
        values[++topIndex]=x;
        return true;
    }
    bool pop(int&x) {
        if(isEmpty())return false;
        x=values[topIndex--];
        return true;
    }
    void Print() {
        for(int i=0;i<=topIndex;i++)cout<<values[i]<<' ';
    }
}
;
int main() {
    int cap,m;
    if(!(cin>>cap>>m)||cap<1||cap>50)return 1;
    Stack s(cap);
    while(m--) {
        char c;
        cin>>c;
        int x;
        if(c=='P') {
            cin>>x;
            if(!s.push(x))cout<<"FULL ";
        }
        else if(c=='O') {
            if(s.pop(x))cout<<x<<' ';
            else cout<<"EMPTY ";
        }
    }
    cout<<"| ";
    s.Print();
}

