#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
bool LaToanTu(string t) {
    return t.size()==1&&string("+-*/^").find(t[0])!=string::npos;
}
int UuTien(string t) {
    if(t=="^")return 3;
    if(t=="*"||t=="/")return 2;
    if(t=="+"||t=="-")return 1;
    return 0;
}
vector<string> Tach(string s) {
    vector<string>a;
    for(size_t i=0;i<s.size();) {
        if(isspace((unsigned char)s[i])) {
            i++;
            continue;
        }
        if(isalnum((unsigned char)s[i])||s[i]=='_') {
            string t;
            while(i<s.size()&&(isalnum((unsigned char)s[i])||s[i]=='_'))t+=s[i++];
            a.push_back(t);
        }
        else a.push_back(string(1,s[i++]));
    }
    return a;
}
vector<string> Chuyen(vector<string>a,bool prefix) {
    if(prefix) {
        reverse(a.begin(),a.end());
        for(string&t:a)if(t=="(")t=")";
        else if(t==")")t="(";
    }
    stack<string>s;
    vector<string>out;
    for(string t:a) {
        if(t=="(")s.push(t);
        else if(t==")") {
            while(!s.empty()&&s.top()!="(") {
                out.push_back(s.top());
                s.pop();
            }
            if(s.empty())throw runtime_error("Lech ngoac");
            s.pop();
        }
        else if(LaToanTu(t)) {
            while(!s.empty()&&LaToanTu(s.top())&&(UuTien(s.top())>UuTien(t)||(UuTien(s.top())==UuTien(t)&&((!prefix&&t!="^")||(prefix&&t=="^"))))) {
                out.push_back(s.top());
                s.pop();
            }
            s.push(t);
        }
        else {
            if(t.empty()||!isalnum((unsigned char)t[0]))throw runtime_error("Token khong hop le");
            out.push_back(t);
        }
    }
    while(!s.empty()) {
        if(s.top()=="(")throw runtime_error("Lech ngoac");
        out.push_back(s.top());
        s.pop();
    }
    if(prefix)reverse(out.begin(),out.end());
    return out;
}
int main() {
    string s;
    getline(cin,s);
    try {
        vector<string>a=Tach(s);
        if(a.empty())throw runtime_error("Rong");
        auto out=Chuyen(a,false);
        int depth=0;
        auto check=out;
        if(false)reverse(check.begin(),check.end());
        for(string t:check) {
            if(LaToanTu(t)) {
                if(depth<2)throw runtime_error("Thieu toan hang");
                depth--;
            }
            else depth++;
        }
        if(depth!=1)throw runtime_error("Thua toan hang");
        for(string t:out)cout<<t<<' ';
    }
    catch(exception&e) {
        cout<<"LOI: "<<e.what();
    }
}

