#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
struct Node {
    int data;
    Node*left,*right;
    Node(int x):data(x),left(NULL),right(NULL) {
    }
}
;
void LNR(Node*t) {
    if(!t)return;
    LNR(t->left);
    cout<<t->data<<' ';
    LNR(t->right);
}
void NLR(Node*t,vector<int>&a) {
    if(!t)return;
    a.push_back(t->data);
    NLR(t->left,a);
    NLR(t->right,a);
}
void LRN(Node*t) {
    if(!t)return;
    LRN(t->left);
    LRN(t->right);
    cout<<t->data<<' ';
}
int Dem(Node*t) {
    return t?1+Dem(t->left)+Dem(t->right):0;
}
int ChieuCao(Node*t) {
    return t?1+max(ChieuCao(t->left),ChieuCao(t->right)):-1;
}
void Huy(Node*&t) {
    if(!t)return;
    Huy(t->left);
    Huy(t->right);
    delete t;
    t=NULL;
}
Node*Doc(vector<int>&a,int i) {
    if(i>=(int)a.size())return NULL;
    Node*t=new Node(a[i]);
    t->left=Doc(a,2*i+1);
    t->right=Doc(a,2*i+2);
    return t;
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>31)return 1;
    vector<int>a(n);
    for(int&i:a)cin>>i;
    Node*root=Doc(a,0);
    vector<int>visit;
    NLR(root,visit);
    for(int x:visit)cout<<x<<' ';
    cout<<"| ";
    LNR(root);
    cout<<"| ";
    LRN(root);
    cout<<"| "<<Dem(root)<<' '<<ChieuCao(root);
    Huy(root);
}

