#include <functional>
using namespace std;
struct Node {
    int data;
    Node*left,*right;
    Node(int x):data(x),left(NULL),right(NULL) {
    }
}
;
void LNR(Node*t) {
    if(!t)return;
    LNR(t->left);
    cout<<t->data<<' ';
    LNR(t->right);
}
void NLR(Node*t,vector<int>&a) {
    if(!t)return;
    a.push_back(t->data);
    NLR(t->left,a);
    NLR(t->right,a);
}
void LRN(Node*t) {
    if(!t)return;
    LRN(t->left);
    LRN(t->right);
    cout<<t->data<<' ';
}
int Dem(Node*t) {
    return t?1+Dem(t->left)+Dem(t->right):0;
}
int ChieuCao(Node*t) {
    return t?1+max(ChieuCao(t->left),ChieuCao(t->right)):-1;
}
void Huy(Node*&t) {
    if(!t)return;
    Huy(t->left);
    Huy(t->right);
    delete t;
    t=NULL;
}
Node*Tim(Node*t,int x) {
    while(t) {
        if(x==t->data)return t;
        t=x<t->data?t->left:t->right;
    }
    return NULL;
}
void ThemNut(Node*&t,int x) {
    if(!t) {
        t=new Node(x);
        return;
    }
    if(x<t->data)ThemNut(t->left,x);
    else if(x>t->data)ThemNut(t->right,x);
}
void Xoa(Node*&t,int x) {
    if(!t)return;
    if(x<t->data)Xoa(t->left,x);
    else if(x>t->data)Xoa(t->right,x);
    else {
        if(!t->left||!t->right) {
            Node*p=t;
            t=t->left?t->left:t->right;
            delete p;
        }
        else {
            Node*p=t->right;
            while(p->left)p=p->left;
            t->data=p->data;
            Xoa(t->right,p->data);
        }
    }
}
int main() {
    int n,m;
    if(!(cin>>n)||n<0||n>50)return 1;
    Node*root=NULL;
    for(int i=0,x;i<n;i++) {
        cin>>x;
        ThemNut(root,x);
    }
    cin>>m;
    while(m--) {
        char c;
        int x;
        cin>>c>>x;
