    Node(int x):data(x),height(0),bal(0),left(NULL),right(NULL) {
    }
}
;
int H(Node*t) {
    return t?t->height:-1;
}
int BF(Node*t) {
    return t?H(t->left)-H(t->right):0;
}
void Update(Node*t) {
    if(t) {
        t->height=1+max(H(t->left),H(t->right));
        t->bal=BF(t);
    }
}
Node*RotateRight(Node*t) {
    Node*p=t->left;
    t->left=p->right;
    p->right=t;
    Update(t);
    Update(p);
    return p;
}
Node*RotateLeft(Node*t) {
    Node*p=t->right;
    t->right=p->left;
    p->left=t;
    Update(t);
    Update(p);
    return p;
}
Node*CanBang(Node*t) {
    if(!t)return t;
    Update(t);
    int b=BF(t);
    if(b>1) {
        if(BF(t->left)<0)t->left=RotateLeft(t->left);
        return RotateRight(t);
    }
    if(b< -1) {
        if(BF(t->right)>0)t->right=RotateRight(t->right);
        return RotateLeft(t);
    }
    return t;
}
