    else {
        if(!t->left||!t->right) {
            Node*p=t;
            t=t->left?t->left:t->right;
            delete p;
        }
        else {
            Node*p=t->right;
            while(p->left)p=p->left;
            t->data=p->data;
            t->right=Xoa(t->right,p->data);
        }
    }
    return CanBang(t);
}
