#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
struct Node {
    int data;
    Node* next;
    Node(int x):data(x),next(NULL) {
    }
}
;
int Count(Node* head,int x) {
    int n=0;
    for(;head;head=head->next) if(head->data==x) n++;
    return n;
}
int GetNth(Node* head,int index) {
    if(index<0) throw out_of_range("index");
    while(head&&index>0) {
        head=head->next;
        index--;
    }
    if(!head) throw out_of_range("index");
    return head->data;
}
void DeleteList(Node*& head) {
    while(head) {
        Node* p=head;
        head=head->next;
        delete p;
    }
}
bool Pop(Node*& head,int& x) {
    if(!head)return false;
    Node* p=head;
    x=p->data;
    head=p->next;
    delete p;
    return true;
}
bool InsertNth(Node*& head,int index,int x) {
    if(index<0)return false;
    Node** link=&head;
    for(int i=0;i<index;i++) {
        if(!*link)return false;
        link=&((*link)->next);
    }
    Node* p=new Node(x);
    p->next=*link;
    *link=p;
    return true;
}
// newNode phải là nút đã tách khỏi danh sách cũ.
void SortedInsert(Node*& head,Node* newNode) {
    Node** link=&head;
    while(*link&&(*link)->data<=newNode->data)link=&((*link)->next);
    newNode->next=*link;
    *link=newNode;
}
void InsertSort(Node*& head) {
    Node* sorted=NULL;
    while(head) {
        Node* p=head;
        head=head->next;
        p->next=NULL;
        SortedInsert(sorted,p);
    }
    head=sorted;
}
void Append(Node*& a,Node*& b) {
    Node** link=&a;
    while(*link)link=&((*link)->next);
    *link=b;
    b=NULL;
}
void FrontBackSplit(Node* source,Node*& front,Node*& back) {
    front=source;
    back=NULL;
    if(!source)return;
    Node* slow=source;
    Node* fast=source->next;
    while(fast&&fast->next) {
        slow=slow->next;
        fast=fast->next->next;
    }
    back=slow->next;
    slow->next=NULL;
}
void RemoveDuplicates(Node* head) {
    while(head&&head->next) {
        if(head->data==head->next->data) {
            Node* p=head->next;
            head->next=p->next;
            delete p;
        }
        else head=head->next;
    }
}
void MoveNode(Node*& dest,Node*& source) {
    if(!source)throw out_of_range("source rong");
    Node* p=source;
    source=p->next;
    p->next=dest;
    dest=p;
}
Node* ShuffleMerge(Node* a,Node* b) {
    Node dummy(0);
    Node* tail=&dummy;
    while(a||b) {
        if(a) {
            tail->next=a;
            a=a->next;
            tail=tail->next;
        }
        if(b) {
            tail->next=b;
            b=b->next;
            tail=tail->next;
        }
    }
    tail->next=NULL;
    return dummy.next;
}
void Print(Node* h) {
    for(;h;h=h->next)cout<<h->data<<' ';
}
int main() {
    int n;
    if(!(cin>>n)||n<1||n>30)return 1;
    Node* head=NULL;
    for(int i=0,x;i<n;i++) {
        cin>>x;
        InsertNth(head,i,x);
    }
    cout<<Count(head,2)<<' '<<GetNth(head,0)<<" | ";
    InsertNth(head,0,9);
    int x;
    Pop(head,x);
    cout<<x<<" | ";
    InsertSort(head);
    SortedInsert(head,new Node(0));
    RemoveDuplicates(head);
    Print(head);
    cout<<"| ";
    Node* front=NULL;
    Node* back=NULL;
    FrontBackSplit(head,front,back);
    head=NULL;
    if(back)MoveNode(front,back);
    Append(front,back);
    FrontBackSplit(front,head,back);
    front=NULL;
    Node* result=ShuffleMerge(head,back);
    head=back=NULL;
    Print(result);
    DeleteList(result);
    cout<<"| "<<(result==NULL);
}

