    istringstream in(line);
    string token;
    stack<Node*> st;
    vector<string> seen;
    while(in>>token) {
        Node* p=new Node(token);
        p->id=(int)seen.size();
        bool op=token.size()==1&&string("+-*/^").find(token)!=string::npos;
