#include <limits>
#include <functional>
using namespace std;
int n;
vector<int> board;
int dx[]= {
    2,1,-1,-2,-2,-1,1,2
}
;
int dy[]= {
    1,2,2,1,-1,-2,-2,-1
}
;
bool ThuMa(int r,int c,int step) {
    board[r*n+c]=step;
    if(step==n*n)return true;
    for(int i=0;i<8;i++) {
        int u=r+dx[i],v=c+dy[i];
        if(u>=0&&u<n&&v>=0&&v<n&&board[u*n+v]==0&&ThuMa(u,v,step+1))return true;
    }
    board[r*n+c]=0;
    return false;
}
int main() {
    if(!(cin>>n)||n<1||n>5)return 1;
    board.assign(n*n,0);
    cout<<(ThuMa(0,0,1)?"CO":"KHONG");
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <stack>
#include <queue>
#include <cmath>
#include <cctype>
#include <stdexcept>
#include <limits>
#include <functional>
using namespace std;
struct Node {
    int data;
    Node*left,*right;
    Node(int x):data(x),left(NULL),right(NULL) {
    }
}
;
struct Stats {
    long long sum,leafSum;
    int size,leaves,height,leftGreater,oddEven,unbalanced;
}
;
Stats Tinh(Node*t) {
    if(!t)return Stats {
        0,0,0,0,-1,0,0,0
    }
    ;
    Stats a=Tinh(t->left),b=Tinh(t->right);
    bool leaf=!t->left&&!t->right;
    Stats s= {
        a.sum+b.sum+t->data,a.leafSum+b.leafSum+(leaf?t->data:0),a.size+b.size+1,a.leaves+b.leaves+(leaf?1:0),1+max(a.height,b.height),a.leftGreater+b.leftGreater+(a.sum>b.sum?1:0),a.oddEven+b.oddEven+(t->left&&t->right&&t->left->data%2==0&&t->right->data%2!=0?1:0),a.unbalanced+b.unbalanced+(abs(a.height-b.height)>1?1:0)
    }
    ;
    return s;
}
Node* Copy(Node*t) {
    if(!t)return NULL;
    Node*p=new Node(t->data);
    p->left=Copy(t->left);
    p->right=Copy(t->right);
    return p;
}
bool LaBST(Node*t,long long lo,long long hi) {
    return !t||(lo<t->data&&t->data<hi&&LaBST(t->left,lo,t->data)&&LaBST(t->right,t->data,hi));
}
bool Tim(Node*t,int x) {
    return t&&(t->data==x||Tim(t->left,x)||Tim(t->right,x));
}
void Huy(Node*t) {
    if(t) {
        Huy(t->left);
        Huy(t->right);
        delete t;
    }
}
Node* Doc(vector<int>&a,int i) {
    if(i>=(int)a.size())return NULL;
    Node*t=new Node(a[i]);
    t->left=Doc(a,2*i+1);
    t->right=Doc(a,2*i+2);
    return t;
}
int main() {
    int n;
    if(!(cin>>n)||n<0||n>31)return 1;
    vector<int>a(n);
    for(int&x:a)cin>>x;
    Node*root=Doc(a,0);
    Stats s=Tinh(root);
    Node*copy=Copy(root);
    cout<<s.size<<' '<<s.sum<<' '<<s.leaves<<' '<<s.leafSum<<' '<<s.height<<' '<<s.leftGreater<<' '<<s.oddEven<<' '<<s.unbalanced<<' '<<LaBST(root,numeric_limits<long long>::min(),numeric_limits<long long>::max());
    Huy(root);
    Huy(copy);
}
